            v = grid[r][c]
            if v != 0:
                color_counts[v] = color_counts.get(v, 0) + 1

    for color in color_counts:
        if color not in bottom_colors:
            # The outline color is typically the most frequent one not in the bottom sequence
            if outline_color is None or color_counts[color] > color_counts.get(outline_color, 0):
