                if (nr, nc) not in exterior and grid[nr][nc] != outline_color:
                    exterior.add((nr, nc))
                    q.append((nr, nc))

    # Find enclosed 0s and apply point reflection
    out_grid = [row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 0 and (r, c) not in exterior:
